<?php
require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';$user=Auth::requireRole('hospital');$hospital=current_hospital($user);if(!request_method('POST'))redirect('hospital/inventory.php');Csrf::verify();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';$q=db()->prepare("SELECT t.*,COALESCE(i.units_available,0) stock FROM blood_transfer_requests t LEFT JOIN blood_inventory i ON i.hospital_id=t.from_hospital_id AND i.blood_group=t.blood_group WHERE t.id=? AND t.from_hospital_id=? AND t.status='pending'");$q->execute([$id,(int)$hospital['id']]);$t=$q->fetch();if(!$t){http_response_code(403);exit('Transfer action not allowed.');}if($action==='accept'){if((int)$t['stock']<(int)$t['units_requested']){flash('error','Prototype inventory is lower than the requested quantity. Update inventory or decline the request.');redirect('hospital/inventory.php');}db()->prepare("UPDATE blood_transfer_requests SET status='accepted',responded_at=NOW() WHERE id=?")->execute([$id]);audit('transfer_accepted','transfer',$id);}elseif($action==='decline'){db()->prepare("UPDATE blood_transfer_requests SET status='declined',responded_at=NOW() WHERE id=?")->execute([$id]);audit('transfer_declined','transfer',$id);}flash('success','Transfer request updated.');redirect('hospital/inventory.php');
